const listNotifications = `-- name: ListNotifications :many
SELECT id, tenant_id, event_type, priority, title, body, data, group_key, created_by, updated_by, expires_at, created_at, updated_at, channels FROM notifications
WHERE ($1::boolean OR tenant_id = $2)
  AND ($3::text IS NULL OR title ILIKE '%' || $3 || '%')
  AND ($4::text IS NULL OR priority = $4::text)
  AND ($5::text IS NULL OR event_type = $5::text)
ORDER BY
  CASE WHEN $6::text = 'created_at' AND $7::text = 'asc' THEN created_at END ASC,
  CASE WHEN $6::text = 'created_at' AND $7::text = 'desc' THEN created_at END DESC,
  CASE WHEN $6::text = 'title' AND $7::text = 'asc' THEN lower(title) END ASC,
  CASE WHEN $6::text = 'title' AND $7::text = 'desc' THEN lower(title) END DESC,
  CASE WHEN $6::text = 'priority' AND $7::text = 'asc' THEN priority END ASC,
  CASE WHEN $6::text = 'priority' AND $7::text = 'desc' THEN priority END DESC,
  id DESC
LIMIT $9 OFFSET $8
`

type ListNotificationsParams struct {
	AllTenants bool    `json:"all_tenants"`
	TenantID   *int64  `json:"tenant_id"`
	Search     string  `json:"search"`
	Priority   *string `json:"priority"`
	EventType  *string `json:"event_type"`
	OrderBy    string  `json:"order_by"`
	OrderDir   string  `json:"order_dir"`
	PageOffset int32   `json:"page_offset"`
	PageLimit  int32   `json:"page_limit"`
}

func (q *Queries) ListNotifications(ctx context.Context, arg ListNotificationsParams) ([]Notification, error) {
	rows, err := q.db.Query(ctx, listNotifications,
		arg.AllTenants,
		arg.TenantID,
		arg.Search,
		arg.Priority,
		arg.EventType,
		arg.OrderBy,
		arg.OrderDir,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Notification{}
	for rows.Next() {
		var i Notification
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.EventType,
			&i.Priority,
			&i.Title,
			&i.Body,
			&i.Data,
			&i.GroupKey,
			&i.CreatedBy,
			&i.UpdatedBy,
			&i.ExpiresAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Channels,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

