const markAllNotificationsRead = `-- name: MarkAllNotificationsRead :execrows
INSERT INTO notification_reads (tenant_id, branch_id, notification_id, user_id, read_at)
SELECT $1, $2, n.id, $3, $4
FROM notifications n
WHERE (n.expires_at IS NULL OR n.expires_at > $4)
  AND ($5::boolean OR n.tenant_id = $1)
  AND EXISTS (
      SELECT 1
      FROM notification_targets t
      WHERE t.notification_id = n.id
        AND (
            (t.target_type = 'USER' AND t.target_id = $3::bigint)
            OR (t.target_type = 'ROLE' AND t.target_id = ANY($6::bigint[]))
            OR (t.target_type = 'BRANCH' AND (
                    ($2::bigint > 0 AND t.target_id = $2::bigint)
                    OR ($7::boolean AND NOT $8::boolean AND n.tenant_id = $1)))
            OR (t.target_type = 'TENANT' AND t.target_id IS NULL
                -- An organization-wide notice reaches that organization's members only,
                -- never a staff account reading across organizations.
                AND NOT $8::boolean AND n.tenant_id = $1)
            OR (t.target_type = 'GLOBAL' AND t.target_id IS NULL AND $8::boolean)
        )
  )
ON CONFLICT (notification_id, user_id) DO NOTHING
`

type MarkAllNotificationsReadParams struct {
	TenantID    *int64             `json:"tenant_id"`
	BranchID    *int64             `json:"branch_id"`
	UserID      int64              `json:"user_id"`
	ReadAt      pgtype.Timestamptz `json:"read_at"`
	AllTenants  bool               `json:"all_tenants"`
	RoleIds     []int64            `json:"role_ids"`
	AllBranches bool               `json:"all_branches"`
	IsNonTenant bool               `json:"is_non_tenant"`
}

func (q *Queries) MarkAllNotificationsRead(ctx context.Context, arg MarkAllNotificationsReadParams) (int64, error) {
	result, err := q.db.Exec(ctx, markAllNotificationsRead,
		arg.TenantID,
		arg.BranchID,
		arg.UserID,
		arg.ReadAt,
		arg.AllTenants,
		arg.RoleIds,
		arg.AllBranches,
		arg.IsNonTenant,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const notificationVisibleToUser = `-- name: NotificationVisibleToUser :one
SELECT EXISTS (
    SELECT 1
    FROM notifications n
    WHERE n.id = $1
      AND ($2::boolean OR n.tenant_id = $3)
      AND EXISTS (
          SELECT 1
          FROM notification_targets t
          WHERE t.notification_id = n.id
            AND (
                (t.target_type = 'USER' AND t.target_id = $4::bigint)
                OR (t.target_type = 'ROLE' AND t.target_id = ANY($5::bigint[]))
                OR (t.target_type = 'BRANCH' AND (
                    ($6::bigint > 0 AND t.target_id = $6::bigint)
                    OR ($7::boolean AND NOT $8::boolean AND n.tenant_id = $3)))
                OR (t.target_type = 'TENANT' AND t.target_id IS NULL
                    -- An organization-wide notice reaches that organization's members only,
                    -- never a staff account reading across organizations.
                    AND NOT $8::boolean AND n.tenant_id = $3)
                OR (t.target_type = 'GLOBAL' AND t.target_id IS NULL AND $8::boolean)
            )
      )
) AS visible
`

type NotificationVisibleToUserParams struct {
	NotificationID int64   `json:"notification_id"`
	AllTenants     bool    `json:"all_tenants"`
	TenantID       *int64  `json:"tenant_id"`
	UserID         int64   `json:"user_id"`
	RoleIds        []int64 `json:"role_ids"`
	BranchID       int64   `json:"branch_id"`
	AllBranches    bool    `json:"all_branches"`
	IsNonTenant    bool    `json:"is_non_tenant"`
}

func (q *Queries) NotificationVisibleToUser(ctx context.Context, arg NotificationVisibleToUserParams) (bool, error) {
	row := q.db.QueryRow(ctx, notificationVisibleToUser,
		arg.NotificationID,
		arg.AllTenants,
		arg.TenantID,
		arg.UserID,
		arg.RoleIds,
		arg.BranchID,
		arg.AllBranches,
		arg.IsNonTenant,
	)
	var visible bool
	err := row.Scan(&visible)
	return visible, err
}

const purgeExpiredNotifications = `-- name: PurgeExpiredNotifications :execrows
DELETE FROM notifications
WHERE expires_at IS NOT NULL AND expires_at < now() - interval '7 days'
`

// Retention: notifications expired for more than a week are invisible in
// every feed query already; their targets/reads/deliveries cascade.
func (q *Queries) PurgeExpiredNotifications(ctx context.Context) (int64, error) {
	result, err := q.db.Exec(ctx, purgeExpiredNotifications)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

